const allTasks = $('Get All Tasks').all().map(i => i.json);
const runs = $('Get Agent Runs').all().map(i => i.json);

const now = new Date();
const yesterday = new Date(now - 86400000);
const dateStr = now.toLocaleDateString('en-US',{weekday:'long',month:'short',day:'numeric',timeZone:'America/New_York'});

const PROJECTS = [
  {name:'Vespera', emoji:'🖤', start:new Date('2026-03-22'), deadline:new Date('2026-03-29')},
  {name:'Kemuni', emoji:'🚀', start:new Date('2026-03-21'), deadline:new Date('2026-04-20')},
  {name:'Infrastructure', emoji:'⚙️', start:null, deadline:null}
];

function progressBar(start, deadline) {
  const total = deadline - start;
  const elapsed = now - start;
  const pct = Math.min(1, Math.max(0, elapsed / total));
  const filled = Math.round(pct * 10);
  return '[' + '▓'.repeat(filled) + '░'.repeat(10-filled) + ']';
}

function statusCategory(status) {
  if (['backlog','defined','open'].includes(status)) return 'Planned';
  if (['in_progress','code_review','product_review','approved'].includes(status)) return 'Ongoing';
  if (['released','completed'].includes(status)) return 'SignOff';
  if (status === 'closed') return 'Done';
  return 'Planned';
}

const recentDone = runs
  .filter(r => ['done','completed','passed'].includes(r.status) && r.started_at && new Date(r.started_at) > yesterday)
  .map(r => r.task_title).filter(Boolean).slice(0,5);

const byProject = {};
for (const p of PROJECTS) byProject[p.name] = {Planned:[], Ongoing:[], SignOff:[], Done:[]};
for (const t of allTasks) {
  const proj = PROJECTS.find(p => p.name === t.project) ? t.project : 'Infrastructure';
  byProject[proj][statusCategory(t.status)].push(t);
}

const critical = allTasks.filter(t =>
  t.priority === 'critical' && ['Planned','Ongoing','SignOff'].includes(statusCategory(t.status)) && !t.title.includes('MANUAL')
);
const criticalTitles = new Set(critical.map(t => t.title));

const todayAll = allTasks.filter(t =>
  ['critical','high'].includes(t.priority) &&
  ['Planned','Ongoing'].includes(statusCategory(t.status)) &&
  !t.title.includes('MANUAL')
).sort((a,b) => (a.priority==='critical'?0:1)-(b.priority==='critical'?0:1));

const inReview = allTasks.filter(t => ['code_review','product_review','approved'].includes(t.status));

let msg = `🧠 *KAOS Daily Brief — ${dateStr}*\n\n`;

if (recentDone.length === 0) {
  msg += `✅ *Done yesterday:* nothing logged\n\n`;
} else if (recentDone.length <= 2) {
  msg += `✅ *Done yesterday:* ${recentDone.map(t=>t.slice(0,40)).join(', ')}\n\n`;
} else {
  msg += `✅ *Done yesterday:*\n` + recentDone.map(t=>`  • ${t.slice(0,45)}`).join('\n') + '\n\n';
}

msg += `━━━ *PROJECTS* ━━━\n\n`;

for (const proj of PROJECTS) {
  const d = byProject[proj.name];
  const daysLeft = proj.deadline ? Math.ceil((proj.deadline - now) / 86400000) : null;
  const bar = proj.start && proj.deadline ? progressBar(proj.start, proj.deadline) + ' ' : '';
  const deadlineStr = daysLeft !== null ? `${bar}${daysLeft}d left` : 'ongoing';

  const counts = `  📦 ${d.Planned.length}  🔄 ${d.Ongoing.length}  ✍️ ${d.SignOff.length}  ✅ ${d.Done.length}`;
  const projToday = todayAll.filter(t => t.project === proj.name && !criticalTitles.has(t.title)).slice(0,3);
  const hasActive = d.Planned.length + d.Ongoing.length + d.SignOff.length > 0;

  msg += `${proj.emoji} *${proj.name}* [${deadlineStr}]\n${counts}\n`;

  if (!hasActive && proj.deadline) {
    msg += `  _No active tasks — needs kickoff_\n`;
  } else if (projToday.length) {
    msg += `  🎯 *Today:*\n` + projToday.map(t=>`  • ${t.title.slice(0,50)}`).join('\n') + '\n';
  }
  msg += '\n';
}

if (inReview.length > 0) {
  msg += `━━━ *👀 REVIEW / SIGN-OFF (${inReview.length})* ━━━\n`;
  inReview.slice(0,4).forEach(t => msg += `  • ${t.title.slice(0,55)} (${(t.status || '').replace(/_/g,' ')})\n`);
  msg += '\n';
}

if (critical.length > 0) {
  msg += `━━━ *🔴 CRITICAL (${critical.length})* ━━━\n`;
  critical.slice(0,5).forEach(t => msg += `  • ${t.title.slice(0,60)}\n`);
  msg += '\n';
}

const totalDone = allTasks.filter(t => statusCategory(t.status)==='Done').length;
const totalActive = allTasks.filter(t => ['Planned','Ongoing','SignOff'].includes(statusCategory(t.status))).length;
msg += `💳 OpenRouter: ~$7.50 · Vercel Pro: renews Apr 24\n`;
msg += `📊 ${totalDone} done · ${totalActive} active · [Mission Control](https://kaos.nabit.work)`;

return [{ json: { text: msg } }];
